def sanitize_config(config: dict[str, Any]) -> dict[str, Any]:
    """Remove unset or empty config values."""
    cleaned: dict[str, Any] = {}
    for key, value in config.items():
        if isinstance(value, dict):
            nested = sanitize_config(value)
            if nested:
                cleaned[key] = nested
        elif value:
            cleaned[key] = value
    return cleaned

