def sanitize_config(config: dict[str, Any]) -> dict[str, Any]:
    cleaned: dict[str, Any] = {}
    for key, value in config.items():
        if isinstance(value, dict):
            nested = sanitize_config(value)
            if nested:
                cleaned[key] = nested
        elif value is not None:
            cleaned[key] = value
    return cleaned

from typing import Union
import enum

class _Missing(enum.Enum):
    MISSING = 'MISSING'

MISSING = _Missing.MISSING

ConfigValue = Union[int, float, str, bool, None]
ConfigEntry = Union[ConfigValue, _Missing]

def sanitize_config(config: dict[str, ConfigEntry]) -> dict[str, ConfigValue]:
    cleaned: dict[str, ConfigValue] = {}
    for key, value in config.items():
        if value is not MISSING:
            if isinstance(value, dict):
                nested = sanitize_config(value)
                if nested:
                    cleaned[key] = nested
            else:
                cleaned[key] = value
    return cleaned

import pytest

class TestMergeSanitizeFalsyValues:
    """Regression tests: falsy values must survive merge + sanitize."""

    def test_zero_int_preserved(self):
        base = {'retries': 3}
        override = {'retries': 0}
        result = sanitize_config(merge_configs(base, override))
        assert result['retries'] == 0

    def test_zero_float_preserved(self):
        base = {'threshold': 1.5}
        override = {'threshold': 0.0}
        result = sanitize_config(merge_configs(base, override))
        assert result['threshold'] == 0.0

    def test_empty_string_preserved(self):
        base = {'prefix': 'default_'}
        override = {'prefix': ''}
        result = sanitize_config(merge_configs(base, override))
        assert result['prefix'] == ''

    def test_false_bool_preserved(self):
        base = {'verbose': True}
        override = {'verbose': False}
        result = sanitize_config(merge_configs(base, override))
        assert result['verbose'] is False

    def test_none_value_stripped(self):
        base = {'key': 'value'}
        override = {'key': None}
        result = sanitize_config(merge_configs(base, override))
        assert 'key' not in result

    def test_nested_falsy_values_preserved(self):
        base = {'db': {'pool_size': 5, 'timeout': 30}}
        override = {'db': {'pool_size': 0}}
        result = sanitize_config(merge_configs(base, override))
        assert result['db']['pool_size'] == 0
        assert result['db']['timeout'] == 30

    def test_empty_nested_dict_stripped(self):
        base = {'section': {'a': None}}
        result = sanitize_config(merge_configs(base, {}))
        assert 'section' not in result

    def test_empty_list_preserved(self):
        base = {'tags': ['default']}
        override = {'tags': []}
        result = sanitize_config(merge_configs(base, override))
        assert result['tags'] == []
